                         // Simplification: Check if cutter center is inside target bounds
                         if (activeCenter.x >= targetBounds.minX && activeCenter.x <= targetBounds.maxX &&
                             activeCenter.z >= targetBounds.minZ && activeCenter.z <= targetBounds.maxZ) {

                             // 2. Vertical Overlap Check
                             // Target Top
                             const targetTop = target.position[1] + target.height;
                             const targetBottom = target.position[1];

                             // Active Shape (Cutter) Range after push
                             // Original Top: shape.position[1]
                             // New Top (visual): shape.position[1] + ppState.dragHeight (where dragHeight is negative)
                             const cutterOriginalTop = shape.position[1];
                             const cutterNewBottom = shape.position[1] + ppState.dragHeight;

                             // Check if we punched through the top surface of target
                             // Usually "drawing on surface" means cutterOriginalTop approx targetTop
                             const isOnTop = Math.abs(cutterOriginalTop - targetTop) < 0.05;

                             if (isOnTop) {
                                 // Check if we pushed deep enough to subtract
                                 // "Exceeds thickness" -> pushed deeper than targetBottom
                                 if (cutterNewBottom <= targetBottom + 0.01) {
                                     // Create Hole!

                                     // Transform cutter points to target's local space
                                     const cutterPointsWorld = shape.points.map(p => transformPoint(p, shape));
                                     const holePointsLocal = cutterPointsWorld.map(p => inverseTransformPoint(p, target));

                                     // Add hole to target
                                     const newHoles = target.holes ? [...target.holes, holePointsLocal] : [holePointsLocal];
                                     updateShape(target.id, { holes: newHoles });

                                     // Remove cutter shape
                                     removeShape(shape.id);
                                     holeCreated = true;
                                     break; // Only punch one hole
                                 }
                             }
