                <SimpleLine key={line.id} points={[line.points[0], line.points[1]]} color="#a855f7" dashed lineWidth={1} depthTest={false} opacity={0.8} />
            ))}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const color = isSelected ? '#3b82f6' : '#333';
    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(p1.distanceTo(p2))}</Text></Billboard>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/80'; let textColor = 'text-white';
    switch(type) {
        case 'vertex': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600'; break;
        case 'endpoint': displayType = '端點 (Endpoint)'; bgColor = 'bg-emerald-600'; break;
        case 'midpoint': displayType = '中點 (Midpoint)'; bgColor = 'bg-cyan-600'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600'; break;
        case 'align': displayType = '對齊 (Align)'; bgColor = 'bg-pink-500'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>{displayText}</div>
        </Html>
    );
};

// ... Managers ...
const usePushPullManager = () => {
    const { tool, updateShape, removeShape, replaceShapes, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = e.intersections.find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;

        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id; 
        else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        // Calculate the world "Up" direction for this shape (which matches its Extrusion direction)
        const euler = new THREE.Euler(...shape.rotation);
        const shapeUp = new THREE.Vector3(0, 1, 0).applyEuler(euler);

        // Check alignment with Shape's Up (Top Face) or Down (Bottom Face)
        const alignment = worldNormal.dot(shapeUp);

        // Allow pushing if we hit the top/bottom face (alignment close to 1 or -1)
        if (Math.abs(alignment) > 0.9) {
             return { mode: 'extrude', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: shapeUp };
        }

        // Otherwise, side logic (Edge resizing) - restricted to roughly horizontal push for simplicity
        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const shapeQuat = new THREE.Quaternion().setFromEuler(euler);
            const invQuat = shapeQuat.clone().invert();
            const localPoint = hitPoint.applyQuaternion(invQuat);
            const xLocal = localPoint.x; const zLocal = localPoint.z;
            let closestIndex = -1; let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) { 
                const p1 = pts[i]; const p2 = pts[(i+1) % pts.length]; 
                const unscaledX = xLocal / shape.scale[0]; const unscaledZ = zLocal / shape.scale[2]; 
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z)); 
                if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; } 
            }
            if (closestIndex !== -1) { 
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize(); 
                return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal }; 
            }
        }
        return null;
    }, [shapes, layers]);

    // Memoize handlers to stabilize ShapeRenderer props
    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            const ndc = new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);

            if (ppState.mode === 'extrude') { 
                // Project mouse ray onto the line defined by drag start + normal
                // A plane perpendicular to camera direction passing through dragStart
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    // Project the vector (target - start) onto the normal vector
                    const dragVector = new THREE.Vector3().subVectors(target, ppState.dragStartPoint);
                    const projection = dragVector.dot(ppState.normal); // This is the delta height

                    const newHeight = ppState.originalHeight + projection;
                    setPPState(prev => ({ ...prev, dragHeight: newHeight })); 
                    setMeasurement(`高度/深度: ${formatValue(newHeight)}`); 
                }
            } 
            else if (ppState.mode === 'side') { 
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3(); 
                raycaster.ray.intersectPlane(dragPlane, target); 
                if (target) { 
                    const diff = target.clone().sub(ppState.dragStartPoint); 
                    const projection = diff.dot(ppState.normal); 
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection); 
                    setMeasurement(`偏移: ${formatValue(projection)}`); 
                    const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)); 
                    const invQuat = shapeQuat.clone().invert(); 
                    const moveVectorLocal = moveVectorWorld.clone().applyQuaternion(invQuat); 
                    const dLocalX = moveVectorLocal.x / shape.scale[0]; 
                    const dLocalZ = moveVectorLocal.z / shape.scale[2]; 
                    const idx = ppState.hoveredEdgeIndex; 
                    const newPoints = ppState.originalPoints.map(p => ({...p})); 
                    const p1 = newPoints[idx]; const p2 = newPoints[(idx+1) % newPoints.length]; 
                    p1.x += dLocalX; p1.z += dLocalZ; p2.x += dLocalX; p2.z += dLocalZ; 
                    const updatedShape = { ...shape, points: newPoints }; 
                    setTempShape(updatedShape); 
                } 
            }
        } else {
            const res = identifyFace(e);
            if (res) { 
                e.stopPropagation(); 
                document.body.style.cursor = res.mode === 'extrude' ? 'ns-resize' : 'ew-resize'; 
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! })); 
            } else { 
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null })); 
                document.body.style.cursor = 'default'; 
            }
        }
    }, [tool, isDragging, ppState, shapes, camera, gl, identifyFace, setMeasurement, formatValue]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();

             // Use the plane of the intersection point for stable dragging start
             const planeNormal = ppState.mode === 'extrude' ? camera.getWorldDirection(new THREE.Vector3()).negate() : new THREE.Vector3(0,1,0);
             const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, e.point); 
             raycaster.ray.intersectPlane(plane, startPoint);

             const pointsCopy = shape.points ? JSON.parse(JSON.stringify(shape.points)) : [];
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: pointsCopy }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    }, [tool, ppState, shapes, camera, gl]);

    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'extrude' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) { 
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (shape) {
                let holeCreated = false;
                if (ppState.dragHeight < 0) {
                     const cutterOriginalY = shape.position[1];
                     const cutterBottomY = cutterOriginalY + ppState.dragHeight;
                     const candidates = shapes.filter(s => s.id !== shape.id && (s.type === 'solid' || s.type === 'flat'));
                     for (const target of candidates) {
                         const targetTop = target.position[1] + target.height;
                         const targetBottom = target.position[1];
                         const startsAtTop = Math.abs(cutterOriginalY - targetTop) < 0.1;
                         const goesThroughBottom = cutterBottomY <= targetBottom + 0.05; 

                         if (startsAtTop && goesThroughBottom) {
                             const cutterPointsWorld = shape.points.map(p => transformPoint(p, shape));
                             const cutterPointsInTargetLocal = cutterPointsWorld.map(p => inverseTransformPoint(p, target));
                             const allPointsInside = cutterPointsInTargetLocal.every(p => isPointInPolygon(p, target.points));

                             if (allPointsInside) {
                                 const newHoles = target.holes ? [...target.holes, cutterPointsInTargetLocal] : [cutterPointsInTargetLocal];
                                 const updatedTarget = { ...target, holes: newHoles };
                                 replaceShapes([shape.id, target.id], [updatedTarget]);
                                 holeCreated = true;
                                 break;
                             }
                         }
                     }
                }

                if (!holeCreated) {
                    const updates: Partial<IShape> = { height: Math.max(0.01, ppState.dragHeight) }; 
                    if (shape.type === 'flat' && updates.height! > 0.05) { 
                        updates.type = 'solid'; 
                        if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR; 
                    } 
                    updateShape(ppState.hoveredShapeId, updates); 
                }
            }
        } 
        else if (tempShapeRef.current) { updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points }); }

        setTempShape(null); 
        setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined })); 
        setMeasurement('');
    }, [updateShape, removeShape, replaceShapes, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);

    useEffect(() => { if (isDragging) { const onGlobalPointerUp = () => handlePointerUp(); window.addEventListener('pointerup', onGlobalPointerUp); return () => window.removeEventListener('pointerup', onGlobalPointerUp); } }, [isDragging, handlePointerUp]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const ShapeRenderer: React.FC<ShapeRendererProps> = React.memo(({ 
    shape, isSelected, pushPullState, pushPullHandlers, 
    drawingHandlers, setDraggingState, onShapeRef 
}) => {
    const groupRef = useRef<THREE.Group>(null);
    const { updateShape, selectedIds } = useApp();
    const isMultiSelected = selectedIds.length > 1;

    useEffect(() => {
        if (groupRef.current) {
            onShapeRef(shape.id, groupRef.current);
        }
    }, [shape.id, onShapeRef]);

    const geometry = useMemo(() => {
        const threeShape = createThreeShape(shape.points, shape.holes);
        if (shape.type === 'solid') {
            return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
        } else {
            return new THREE.ShapeGeometry(threeShape);
        }
    }, [shape.points, shape.holes, shape.type, shape.height]);

    const material = useMemo(() => {
        const color = isSelected ? HIGHLIGHT_COLOR : (shape.type === 'flat' ? (shape.color === DEFAULT_COLOR ? FLAT_COLOR : shape.color) : shape.color);
        const opacity = shape.type === 'flat' ? 0.5 : 1;
        return new THREE.MeshStandardMaterial({ color, transparent: shape.type === 'flat', opacity, side: THREE.DoubleSide });
    }, [shape.color, shape.type, isSelected]);

    return (
        <group 
            ref={groupRef}
            position={new THREE.Vector3(...shape.position)} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={new THREE.Vector3(...shape.scale)}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                 e.stopPropagation();
                 drawingHandlers.handleClick(e);
            }}
            onPointerDown={(e) => {
                pushPullHandlers.handlePointerDown(e);
                drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={pushPullHandlers.handlePointerMove}
            onPointerUp={pushPullHandlers.handlePointerUp}
        >
             <mesh
                geometry={geometry}
                material={material}
                rotation={[-Math.PI / 2, 0, 0]}
                receiveShadow
                castShadow
            >
                {isSelected && <Edges color="white" linewidth={2} />}
            </mesh>
            {isSelected && !isMultiSelected && <DimensionShape shape={shape} isSelected={isSelected} onSelect={() => {}} />}
        </group>
    );
});

const SceneContent: React.FC = () => {
    const { 
        shapes, tool, selectedIds, selectShape, updateShape, 
        addShape, guideLines, activeLayerId, layers, transformMode, 
        formatValue, setMeasurement, deselectAll
    } = useApp();
    const { camera, gl } = useThree();
    const [drawingPoints, setDrawingPoints] = useState<IPoint[]>([]);
    const [mousePos, setMousePos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const shapeRefs = useRef<Record<string, THREE.Group | null>>({});

    const ppManager = usePushPullManager();

    useEffect(() => {
        setDrawingPoints([]);
        setSnapInfo(null);
    }, [tool]);

    const getGroundPoint = (e: ThreeEvent<PointerEvent>) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, target);
        return target || new THREE.Vector3(0, 0, 0);
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        const groundP = getGroundPoint(e);
        const ray = new THREE.Ray(camera.position, groundP.clone().sub(camera.position).normalize());

        const shouldSnap = [ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.MEASURE].includes(tool);
        let snap: SnapResult = { position: groundP, type: 'none', distance: 0, normal: new THREE.Vector3(0,1,0) };

        if (shouldSnap) {
             snap = getGeometrySnap(groundP, ray, shapes, drawingPoints, SNAP_THRESHOLD);
             if (snap.type === 'none' || snap.type === 'grid') {
                 snap.position.set(
                     Math.round(groundP.x / SNAP_GRID) * SNAP_GRID,
                     0,
                     Math.round(groundP.z / SNAP_GRID) * SNAP_GRID
                 );
                 snap.type = 'grid';
             }
        }

        setSnapInfo(snap);
        setMousePos(snap.position);

        if (drawingPoints.length > 0) {
            const start = drawingPoints[drawingPoints.length - 1];
            const dist = Math.sqrt((snap.position.x - start.x)**2 + (snap.position.z - start.z)**2);
            setMeasurement(`距離: ${formatValue(dist)}`);
        } else {
            if (tool === ToolType.SELECT && !ppManager.isDragging) setMeasurement('');
        }

        if (tool === ToolType.PUSH_PULL) {
            ppManager.handlePointerMove(e);
        }
    };

    const handleCanvasClick = (e: ThreeEvent<MouseEvent>) => {
        if (isDragging) return;

        if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) {
            const p = { x: mousePos.x, y: 0, z: mousePos.z };

            if (tool === ToolType.DRAW_RECT) {
                if (drawingPoints.length === 0) {
                    setDrawingPoints([p]);
                } else {
                    const start = drawingPoints[0];
                    const width = Math.abs(p.x - start.x);
                    const depth = Math.abs(p.z - start.z);
                    if (width < 0.1 || depth < 0.1) return;

                    const center = { x: (start.x + p.x)/2, z: (start.z + p.z)/2 };
                    const halfW = width / 2;
                    const halfD = depth / 2;

                    const points = [
                        { x: -halfW, y: 0, z: -halfD },
                        { x: halfW, y: 0, z: -halfD },
                        { x: halfW, y: 0, z: halfD },
                        { x: -halfW, y: 0, z: halfD },
                        { x: -halfW, y: 0, z: -halfD }
                    ];

                    addShape({
                        id: `rect-${Date.now()}`,
                        type: 'solid',
                        points,
                        height: 3,
                        color: DEFAULT_COLOR,
                        layerId: activeLayerId,
                        position: [center.x, 0, center.z],
                        rotation: [0, 0, 0],
                        scale: [1, 1, 1],
                        name: 'Room'
                    });
                    setDrawingPoints([]);
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 if (drawingPoints.length === 0) setDrawingPoints([p]);
                 else {
                     const center = drawingPoints[0];
                     const radius = Math.sqrt((p.x - center.x)**2 + (p.z - center.z)**2);
                     if (radius < 0.1) return;
                     const points = createCirclePoints(radius);
                     addShape({
                        id: `circle-${Date.now()}`,
                        type: 'flat',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        layerId: activeLayerId,
                        position: [center.x, 0, center.z],
                        rotation: [0, 0, 0],
                        scale: [1, 1, 1],
                        name: 'Circle'
                     });
                     setDrawingPoints([]);
                 }
            } else if (tool === ToolType.DRAW_LINE) {
                setDrawingPoints(prev => [...prev, p]);
                if (drawingPoints.length > 2) {
                    const start = drawingPoints[0];
                    const dist = Math.sqrt((p.x - start.x)**2 + (p.z - start.z)**2);
                    if (dist < 0.3) {
                         const minX = Math.min(...drawingPoints.map(dp=>dp.x));
                         const maxX = Math.max(...drawingPoints.map(dp=>dp.x));
                         const minZ = Math.min(...drawingPoints.map(dp=>dp.z));
                         const maxZ = Math.max(...drawingPoints.map(dp=>dp.z));
                         const centerX = (minX + maxX)/2;
                         const centerZ = (minZ + maxZ)/2;

                         const localPoints = drawingPoints.map(dp => ({ x: dp.x - centerX, y: 0, z: dp.z - centerZ }));
                         localPoints.push(localPoints[0]);

                         addShape({
                            id: `poly-${Date.now()}`,
                            type: 'flat',
                            points: localPoints,
                            height: DEFAULT_HEIGHT,
                            color: FLAT_COLOR,
                            layerId: activeLayerId,
                            position: [centerX, 0, centerZ],
                            rotation: [0, 0, 0],
                            scale: [1, 1, 1],
                            name: 'Polygon'
                        });
                        setDrawingPoints([]);
                    }
                }
            }
        }
        else if (tool === ToolType.SELECT) {
             if (!e.intersections.some(i => i.object.userData?.isShape || i.object.parent?.userData?.isShape)) {
                 deselectAll();
             }
        }
    };

    const activeTransformMode = tool === ToolType.ROTATE ? 'rotate' : transformMode;
    const showTransformControls = selectedIds.length === 1 && (tool === ToolType.SELECT || tool === ToolType.ROTATE);

    return (
        <>
            <gridHelper args={[100, 100, 0xdddddd, 0xeeeeee]} />
            <axesHelper args={[5]} />
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow />

            <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]} 
                onPointerMove={handlePointerMove} 
                onClick={handleCanvasClick}
                visible={false}
            >
                <planeGeometry args={[1000, 1000]} />
            </mesh>

            <GuideLinesRenderer lines={guideLines} />

            {shapes.map(shape => {
                const layer = layers.find(l => l.id === shape.layerId);
                if (layer && !layer.visible) return null;

                return (
                    <ShapeRenderer 
                        key={shape.id} 
                        shape={ppManager.tempShape?.id === shape.id ? ppManager.tempShape : shape}
                        isSelected={selectedIds.includes(shape.id)}
                        pushPullState={ppManager.ppState}
                        pushPullHandlers={ppManager}
                        drawingHandlers={{ 
                            handlePointerDown: (e) => {
                                if (tool === ToolType.SELECT) {
                                    e.stopPropagation();
                                    const multi = e.shiftKey;
                                    selectShape(shape.id, multi);
                                }
                            },
                            handlePointerUp: () => {},
                            handleClick: (e) => {}
                        }}
                        rotateHandlers={{ handleClick: () => {}, handlePointerMove: () => {} }}
                        setDraggingState={setIsDragging}
                        onShapeRef={(id, ref) => { shapeRefs.current[id] = ref; }}
                        shapeRefs={shapeRefs}
                        setAlignmentLines={() => {}}
                    />
                );
            })}

            {drawingPoints.length > 0 && (
                <group>
                    {drawingPoints.map((p, i) => (
                        <mesh key={i} position={[p.x, 0.1, p.z]}>
                            <sphereGeometry args={[0.05]} />
                            <meshBasicMaterial color="red" />
                        </mesh>
                    ))}
                    {tool === ToolType.DRAW_RECT && (
                         <SimpleLine points={[
                            new THREE.Vector3(drawingPoints[0].x, 0.1, drawingPoints[0].z),
                            new THREE.Vector3(mousePos.x, 0.1, drawingPoints[0].z),
                            new THREE.Vector3(mousePos.x, 0.1, mousePos.z),
                            new THREE.Vector3(drawingPoints[0].x, 0.1, mousePos.z),
                            new THREE.Vector3(drawingPoints[0].x, 0.1, drawingPoints[0].z)
                         ]} color="blue" />
                    )}
                    {tool === ToolType.DRAW_CIRCLE && (
                         <SimpleLine points={[
                             new THREE.Vector3(drawingPoints[0].x, 0.1, drawingPoints[0].z),
                             new THREE.Vector3(mousePos.x, 0.1, mousePos.z)
                         ]} color="blue" dashed />
                    )}
                    {tool === ToolType.DRAW_LINE && (
                         <SimpleLine points={[...drawingPoints.map(p => new THREE.Vector3(p.x, 0.1, p.z)), new THREE.Vector3(mousePos.x, 0.1, mousePos.z)]} color="blue" />
                    )}
                </group>
            )}

            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {snapInfo && <CursorTooltip text={snapInfo.type !== 'grid' && snapInfo.type !== 'none' ? snapInfo.type : ''} position={snapInfo.position} type={snapInfo.type} />}

            {showTransformControls && shapeRefs.current[selectedIds[0]] && (
                <TransformControls 
                    object={shapeRefs.current[selectedIds[0]]!} 
                    mode={activeTransformMode} 
                    onDragging-changed={(e) => setIsDragging(e.value)}
                    onMouseUp={() => {
                        const obj = shapeRefs.current[selectedIds[0]];
                        if (obj) {
                             updateShape(selectedIds[0], {
                                 position: [obj.position.x, obj.position.y, obj.position.z],
                                 rotation: [obj.rotation.x, obj.rotation.y, obj.rotation.z],
                                 scale: [obj.scale.x, obj.scale.y, obj.scale.z]
                             });
                        }
                    }}
                />
            )}
        </>
    );
};

const Viewport: React.FC = () => {
    const { currentView, setCurrentView } = useApp();
    const orbitRef = useRef<any>(null);

    useEffect(() => {
        if (!currentView || !orbitRef.current) return;
        const controls = orbitRef.current;
        switch (currentView) {
            case 'top':
                controls.object.position.set(0, 20, 0);
                controls.object.lookAt(0, 0, 0);
                break;
            case 'front':
                controls.object.position.set(0, 2, 20);
                controls.object.lookAt(0, 2, 0);
                break;
            case 'right':
                controls.object.position.set(20, 2, 0);
                controls.object.lookAt(0, 2, 0);
                break;
            case 'left':
                 controls.object.position.set(-20, 2, 0);
                 controls.object.lookAt(0, 2, 0);
                 break;
            case 'bottom':
                 controls.object.position.set(0, -20, 0);
                 controls.object.lookAt(0, 0, 0);
                 break;
        }
        controls.update();
        setCurrentView(null);
    }, [currentView, setCurrentView]);

    return (
        <div className="w-full h-full bg-slate-100">
            <Canvas shadows camera={{ position: [8, 8, 8], fov: 45 }}>
                <OrbitControls ref={orbitRef} makeDefault />
                <SceneContent />
                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#9d4b4b', '#2f7f4f', '#3b5b9d']} labelColor="white" />
                </GizmoHelper>
            </Canvas>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Edges, Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Ray distance threshold
const ALIGN_THRESHOLD = 0.3;
const EPSILON = 1e-4;

// --- Helper: Get Local Basis Vectors from Normal ---
const getLocalBasis = (normal: THREE.Vector3) => {
    const n = normal.clone().normalize();
    let up = new THREE.Vector3(0, 1, 0);
    if (Math.abs(n.dot(up)) > 0.99) up.set(0, 0, 1);

    const right = new THREE.Vector3().crossVectors(n, up).normalize();
    const top = new THREE.Vector3().crossVectors(right, n).normalize(); 

    return { right, top, normal: n };
};

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

type PushPullMode = 'extrude' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface RotateState {
    phase: 'hover' | 'set-start' | 'rotating';
    pivot: THREE.Vector3 | null;
    axis: THREE.Vector3 | null;
    startVector: THREE.Vector3 | null;
    currentAngle: number;
    initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }>;
    lockedAxis: THREE.Vector3 | null;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    rotateHandlers: {
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    onShapeRef: (id: string, ref: THREE.Group | null) => void;
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---

// Helper to remove duplicate consecutive points and closing points
const cleanPathPoints = (points: {x: number, y: number}[]) => {
    if (points.length < 3) return points;

    // 1. Remove consecutive duplicates
    const uniquePoints = points.filter((p, i) => {
        if (i === 0) return true;
        const prev = points[i - 1];
        const distSq = (p.x - prev.x) ** 2 + (p.y - prev.y) ** 2;
        return distSq > EPSILON;
    });

    // 2. Remove duplicate end point if it matches start
    if (uniquePoints.length > 2) {
        const first = uniquePoints[0];
        const last = uniquePoints[uniquePoints.length - 1];
        const distSq = (first.x - last.x) ** 2 + (first.y - last.y) ** 2;
        if (distSq < EPSILON) {
            uniquePoints.pop();
        }
    }

    return uniquePoints;
};

// Ray-casting algorithm for point in polygon
const isPointInPolygon = (point: {x: number, z: number}, vs: IPoint[]) => {
    let x = point.x, z = point.z;
    let inside = false;
    for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
        let xi = vs[i].x, zi = vs[i].z;
        let xj = vs[j].x, zj = vs[j].z;
        let intersect = ((zi > z) !== (zj > z))
            && (x < (xj - xi) * (z - zi) / (zj - zi) + xi);
        if (intersect) inside = !inside;
    }
    return inside;
};

const createThreeShape = (points: IPoint[], holes?: IPoint[][]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  // Map 3D points (x, z) to 2D Shape points (x, y)
  // Note: We map z to -y to handle the coordinate rotation later
  let shapePoints = points.map(p => ({ x: p.x, y: -p.z }));

  // Clean points (remove duplicate end point) to avoid triangulation issues
  shapePoints = cleanPathPoints(shapePoints);

  // Use Three.js utility to calculate signed area
  // Area > 0 is Counter-Clockwise (CCW)
  // Area < 0 is Clockwise (CW)
  const area = THREE.ShapeUtils.area(shapePoints);

  // Ensure Outer shape is Counter-Clockwise (CCW) for ExtrudeGeometry
  if (area < 0) {
      shapePoints.reverse();
  }

  shape.setFromPoints(shapePoints.map(p => new THREE.Vector2(p.x, p.y)));
  shape.closePath();

  // Add holes
  if (holes && holes.length > 0) {
      holes.forEach(holePointsRaw => {
          if (!holePointsRaw || holePointsRaw.length < 3) return;
          const holePath = new THREE.Path();
          let pathPoints = holePointsRaw.map(p => ({ x: p.x, y: -p.z }));

          pathPoints = cleanPathPoints(pathPoints);

          // Calculate area for hole
          const holeArea = THREE.ShapeUtils.area(pathPoints);

          // Ensure Holes are Clockwise (CW) for ExtrudeGeometry
          // If area is positive (CCW), reverse it
          if (holeArea > 0) {
              pathPoints.reverse();
          }

          holePath.setFromPoints(pathPoints.map(p => new THREE.Vector2(p.x, p.y)));
          holePath.closePath();
          shape.holes.push(holePath);
      });
  }

  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const v = new THREE.Vector3(localP.x, 0, localP.z);
    v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
    const euler = new THREE.Euler(...shape.rotation);
    v.applyEuler(euler);
    v.add(new THREE.Vector3(...shape.position));
    return v;
};

// Transform a world point back into the local 2D plane (X/Z) of a shape
const inverseTransformPoint = (worldP: THREE.Vector3, shape: IShape): IPoint => {
    const v = worldP.clone();
    v.sub(new THREE.Vector3(...shape.position));

    const euler = new THREE.Euler(...shape.rotation);
    const quaternion = new THREE.Quaternion().setFromEuler(euler);
    v.applyQuaternion(quaternion.invert());

    // Scale is tricky for inverse if 0, but assuming non-zero
    const x = shape.scale[0] !== 0 ? v.x / shape.scale[0] : 0;
    const z = shape.scale[2] !== 0 ? v.z / shape.scale[2] : 0;

    return { x, y: 0, z };
};

const getShapeBounds = (shape: IShape, currentPos?: THREE.Vector3) => {
    const pos = currentPos || new THREE.Vector3(...shape.position);
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    const tempShape = { ...shape, position: [pos.x, pos.y, pos.z] as [number, number, number] };
    shape.points.forEach(p => {
         const wp = transformPoint(p, tempShape as IShape);
         if(wp.x < minX) minX = wp.x;
         if(wp.x > maxX) maxX = wp.x;
         if(wp.z < minZ) minZ = wp.z;
         if(wp.z > maxZ) maxZ = wp.z;
    });
    return { minX, maxX, minZ, maxZ, centerX: (minX + maxX) / 2, centerZ: (minZ + maxZ) / 2, y: pos.y };
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= -EPSILON && u <= 1 + EPSILON && v >= -EPSILON && v <= 1 + EPSILON) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection { point: IPoint; edgeIndex: number; dist: number; }
    const intersections: Intersection[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);
        if (hit) {
            const isDuplicate = intersections.some(intr => Math.abs(intr.point.x - hit.x) < 0.001 && Math.abs(intr.point.z - hit.z) < 0.001);
            if (!isDuplicate) {
                const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }
    if (intersections.length < 2) return null;
    intersections.sort((a, b) => a.dist - b.dist);
    const [startHit, endHit] = intersections;
    const getVerticesBetween = (idx1: number, idx2: number) => {
        const verts: IPoint[] = [];
        let i = (idx1 + 1) % polyPoints.length;
        while (i !== (idx2 + 1) % polyPoints.length) {
            verts.push(polyPoints[i]);
            i = (i + 1) % polyPoints.length;
        }
        return verts;
    };
    const polyA_verts = getVerticesBetween(startHit.edgeIndex, endHit.edgeIndex);
    const polyA = [startHit.point, ...polyA_verts, endHit.point];
    const polyB_verts = getVerticesBetween(endHit.edgeIndex, startHit.edgeIndex);
    const polyB = [endHit.point, ...polyB_verts, startHit.point];
    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;
    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => { if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x; });
    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];
    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const euler = new THREE.Euler(...shape.rotation);
    const quat = new THREE.Quaternion().setFromEuler(euler);
    const left = new THREE.Vector3(-scaledHalfLen, 0, 0).applyQuaternion(quat);
    const right = new THREE.Vector3(scaledHalfLen, 0, 0).applyQuaternion(quat);
    return [pos.clone().add(left), pos.clone().add(right)];
};

const fragmentSegments = (segments: { start: IPoint; end: IPoint }[]): { start: IPoint; end: IPoint }[] => {
    let currentSegments = [...segments];
    let hasIntersections = true;
    let iterations = 0;
    while (hasIntersections && iterations < 50) {
        hasIntersections = false;
        iterations++;
        const newSegments: { start: IPoint; end: IPoint }[] = [];
        const processed = new Set<number>();
        for (let i = 0; i < currentSegments.length; i++) {
            if (processed.has(i)) continue;
            let s1 = currentSegments[i];
            let broken = false;
            for (let j = i + 1; j < currentSegments.length; j++) {
                if (processed.has(j)) continue;
                let s2 = currentSegments[j];
                const intersection = getSegmentIntersection(s1.start, s1.end, s2.start, s2.end);
                const isEndpoint = (p: IPoint, s: {start: IPoint, end: IPoint}) => (Math.abs(p.x - s.start.x) < 0.001 && Math.abs(p.z - s.start.z) < 0.001) || (Math.abs(p.x - s.end.x) < 0.001 && Math.abs(p.z - s.end.z) < 0.001);
                if (intersection && !isEndpoint(intersection, s1) && !isEndpoint(intersection, s2)) {
                    newSegments.push({ start: s1.start, end: intersection });
                    newSegments.push({ start: intersection, end: s1.end });
                    newSegments.push({ start: s2.start, end: intersection });
                    newSegments.push({ start: intersection, end: s2.end });
                    processed.add(i); processed.add(j);
                    broken = true; hasIntersections = true; break; 
                }
            }
            if (!broken) newSegments.push(s1);
        }
        if (hasIntersections) currentSegments = newSegments;
    }
    return currentSegments;
};

const getBoundingCenter = (points: IPoint[]) => {
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
    return { x: (minX + maxX) / 2, z: (minZ + maxZ) / 2 };
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    ray: THREE.Ray,
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let fallbackSnap: SnapResult;
    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
        let normal = new THREE.Vector3(0, 1, 0);
        if (intersectedObject.face) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
            normal = intersectedObject.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        }
        fallbackSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id, normal };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID, cursorPos.y, Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID),
            type: 'grid', distance: Infinity, normal: new THREE.Vector3(0, 1, 0)
        };
    }
    let bestVertexSnap: SnapResult | null = null;
    let bestEdgeSnap: SnapResult | null = null;
    let minVertexDist = threshold;
    let minEdgeDist = threshold;
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ray.distanceToPoint(ptVec);
        if (dist < threshold * 1.5) {
            bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist, normal: new THREE.Vector3(0,1,0) };
            minVertexDist = dist;
        }
    }
    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 const edgeVec = new THREE.Vector3().subVectors(endpoints[1], endpoints[0]).normalize();
                 for(const ep of endpoints) {
                     const dist = ray.distanceToPoint(ep);
                     if (dist < minVertexDist) {
                         bestVertexSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id, normal: edgeVec };
                         minVertexDist = dist;
                     }
                 }
                 continue; 
             }
        }
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = ray.distanceToPoint(worldPt);
            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = transformPoint(shape.points[i], { ...shape, position: [shape.position[0], shape.position[1] + currentH, shape.position[2]] });
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                    minVertexDist = dist;
                }
            }
        }
    }
    if (!bestVertexSnap || bestVertexSnap.distance > 0.1) {
        for (const shape of shapes) {
            const pts = shape.points;
            const len = pts.length;
            const currentH = shape.height * shape.scale[1];
            const hasHeight = Math.abs(currentH) > 0.001;
            const getWorldPos = (localX: number, localY: number, localZ: number) => {
                 const v = new THREE.Vector3(localX, localY, localZ);
                 v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
                 v.applyEuler(new THREE.Euler(...shape.rotation));
                 v.add(new THREE.Vector3(...shape.position));
                 return v;
            }
            for (let i = 0; i < len; i++) {
                const p1 = getWorldPos(pts[i].x, 0, pts[i].z);
                const p2 = getWorldPos(pts[(i + 1) % len].x, 0, pts[(i + 1) % len].z);
                const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                    const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                    const distMid = ray.distanceToPoint(mid);
                    const edgeVec = new THREE.Vector3().subVectors(v2, v1).normalize();
                    if (distMid < minEdgeDist) {
                        bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                        minEdgeDist = distMid;
                    }
                    const pointOnSegment = new THREE.Vector3();
                    const distSq = ray.distanceSqToSegment(v1, v2, undefined, pointOnSegment);
                    const distEdge = Math.sqrt(distSq);
                    if (distEdge < minEdgeDist) {
                         if (bestEdgeSnap?.type === 'midpoint' && bestEdgeSnap.distance < distEdge + 0.1) {} else {
                             bestEdgeSnap = { position: pointOnSegment, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                             minEdgeDist = distEdge;
                         }
                    }
                };
                checkSegment(p1, p2);
                if (hasHeight) {
                    const p1Top = getWorldPos(pts[i].x, shape.height, pts[i].z);
                    const p2Top = getWorldPos(pts[(i + 1) % len].x, shape.height, pts[(i + 1) % len].z);
                    checkSegment(p1Top, p2Top); checkSegment(p1, p1Top);
                }
            }
        }
    }
    if (bestVertexSnap && bestEdgeSnap) {
        if (bestVertexSnap.distance < bestEdgeSnap.distance * 1.5) return bestVertexSnap;
        else return bestEdgeSnap;
    }
    if (bestVertexSnap) return bestVertexSnap;
    if (bestEdgeSnap) return bestEdgeSnap;
    return fallbackSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);
    useLayoutEffect(() => {
        if (dashed && ref.current) ref.current.computeLineDistances();
    }, [geometry, dashed]);
    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? ( <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> ) : ( <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> )}
        </line>
    );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return (
        <group renderOrder={9999}>
            {lines.map((line) => (
                <SimpleLine key={line.id} points={[line.points[0], line.points[1]]} color="#a855f7" dashed lineWidth={1} depthTest={false} opacity={0.8} />
            ))}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const color = isSelected ? '#3b82f6' : '#333';
    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(p1.distanceTo(p2))}</Text></Billboard>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/80'; let textColor = 'text-white';
    switch(type) {
        case 'vertex': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600'; break;
        case 'endpoint': displayType = '端點 (Endpoint)'; bgColor = 'bg-emerald-600'; break;
        case 'midpoint': displayType = '中點 (Midpoint)'; bgColor = 'bg-cyan-600'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600'; break;
        case 'align': displayType = '對齊 (Align)'; bgColor = 'bg-pink-500'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>{displayText}</div>
        </Html>
    );
};

// ... Managers ...
const usePushPullManager = () => {
    const { tool, updateShape, removeShape, replaceShapes, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = e.intersections.find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;

        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id; 
        else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        // Calculate the world "Up" direction for this shape (which matches its Extrusion direction)
        const euler = new THREE.Euler(...shape.rotation);
        const shapeUp = new THREE.Vector3(0, 1, 0).applyEuler(euler);

        // Check alignment with Shape's Up (Top Face) or Down (Bottom Face)
        const alignment = worldNormal.dot(shapeUp);

        // Allow pushing if we hit the top/bottom face (alignment close to 1 or -1)
        if (Math.abs(alignment) > 0.9) {
             return { mode: 'extrude', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: shapeUp };
        }

        // Otherwise, side logic (Edge resizing) - restricted to roughly horizontal push for simplicity
        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const shapeQuat = new THREE.Quaternion().setFromEuler(euler);
            const invQuat = shapeQuat.clone().invert();
            const localPoint = hitPoint.applyQuaternion(invQuat);
            const xLocal = localPoint.x; const zLocal = localPoint.z;
            let closestIndex = -1; let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) { 
                const p1 = pts[i]; const p2 = pts[(i+1) % pts.length]; 
                const unscaledX = xLocal / shape.scale[0]; const unscaledZ = zLocal / shape.scale[2]; 
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z)); 
                if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; } 
            }
            if (closestIndex !== -1) { 
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize(); 
                return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal }; 
            }
        }
        return null;
    }, [shapes, layers]);

    // Memoize handlers to stabilize ShapeRenderer props
    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            const ndc = new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);

            if (ppState.mode === 'extrude') { 
                // Project mouse ray onto the line defined by drag start + normal
                // A plane perpendicular to camera direction passing through dragStart
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    // Project the vector (target - start) onto the normal vector
                    const dragVector = new THREE.Vector3().subVectors(target, ppState.dragStartPoint);
                    const projection = dragVector.dot(ppState.normal); // This is the delta height

                    const newHeight = ppState.originalHeight + projection;
                    setPPState(prev => ({ ...prev, dragHeight: newHeight })); 
                    setMeasurement(`高度/深度: ${formatValue(newHeight)}`); 
                }
            } 
            else if (ppState.mode === 'side') { 
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3(); 
                raycaster.ray.intersectPlane(dragPlane, target); 
                if (target) { 
                    const diff = target.clone().sub(ppState.dragStartPoint); 
                    const projection = diff.dot(ppState.normal); 
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection); 
                    setMeasurement(`偏移: ${formatValue(projection)}`); 
                    const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)); 
                    const invQuat = shapeQuat.clone().invert(); 
                    const moveVectorLocal = moveVectorWorld.clone().applyQuaternion(invQuat); 
                    const dLocalX = moveVectorLocal.x / shape.scale[0]; 
                    const dLocalZ = moveVectorLocal.z / shape.scale[2]; 
                    const idx = ppState.hoveredEdgeIndex; 
                    const newPoints = ppState.originalPoints.map(p => ({...p})); 
                    const p1 = newPoints[idx]; const p2 = newPoints[(idx+1) % newPoints.length]; 
                    p1.x += dLocalX; p1.z += dLocalZ; p2.x += dLocalX; p2.z += dLocalZ; 
                    const updatedShape = { ...shape, points: newPoints }; 
                    setTempShape(updatedShape); 
                } 
            }
        } else {
            const res = identifyFace(e);
            if (res) { 
                e.stopPropagation(); 
                document.body.style.cursor = res.mode === 'extrude' ? 'ns-resize' : 'ew-resize'; 
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! })); 
            } else { 
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null })); 
                document.body.style.cursor = 'default'; 
            }
        }
    }, [tool, isDragging, ppState, shapes, camera, gl, identifyFace, setMeasurement, formatValue]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();

             // Use the plane of the intersection point for stable dragging start
             const planeNormal = ppState.mode === 'extrude' ? camera.getWorldDirection(new THREE.Vector3()).negate() : new THREE.Vector3(0,1,0);
             const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, e.point); 
             raycaster.ray.intersectPlane(plane, startPoint);

             const pointsCopy = shape.points ? JSON.parse(JSON.stringify(shape.points)) : [];
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: pointsCopy }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    }, [tool, ppState, shapes, camera, gl]);

    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'extrude' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) { 
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (shape) {
                let holeCreated = false;

                // Push-Cut Logic
                // Condition: Dragging downwards (negative)
                if (ppState.dragHeight < 0) {
                     // The cutter's visual bottom face during drag (which corresponds to its original position Y + dragHeight)
                     // However, effectively, the cutter volume spans from [shape.position.y] to [shape.position.y + dragHeight]
                     // Since dragHeight is negative, it goes DOWN from shape.position.y

                     const cutterOriginalY = shape.position[1];
                     const cutterBottomY = cutterOriginalY + ppState.dragHeight;

                     // Filter potential targets (must be solid or flat, not self)
                     const candidates = shapes.filter(s => s.id !== shape.id && (s.type === 'solid' || s.type === 'flat'));

                     for (const target of candidates) {
                         const targetTop = target.position[1] + target.height;
                         const targetBottom = target.position[1];

                         // 1. Vertical Overlap Check
                         // Cutter MUST start roughly at target top and go roughly to/through target bottom
                         const startsAtTop = Math.abs(cutterOriginalY - targetTop) < 0.1;
                         const goesThroughBottom = cutterBottomY <= targetBottom + 0.05; // slight tolerance

                         if (startsAtTop && goesThroughBottom) {
                             // 2. Horizontal Containment Check (using local coordinates)
                             // Transform cutter's points to target's local space
                             const cutterPointsWorld = shape.points.map(p => transformPoint(p, shape));
                             const cutterPointsInTargetLocal = cutterPointsWorld.map(p => inverseTransformPoint(p, target));

                             // Check if all vertices of the cutter are inside the target polygon
                             // This ensures clean cuts. SketchUp allows partial cuts but that requires CSG.
                             // We stick to full containment for simplicity without external libraries.
                             const allPointsInside = cutterPointsInTargetLocal.every(p => isPointInPolygon(p, target.points));

                             if (allPointsInside) {
                                 // Execute Cut
                                 // Add hole to target
                                 // Ensure correct winding order for hole (Clockwise) is handled by createThreeShape later
                                 // but we store raw points here.
                                 const newHoles = target.holes ? [...target.holes, cutterPointsInTargetLocal] : [cutterPointsInTargetLocal];

                                 // FIX: Use replaceShapes to atomically update target and remove cutter
                                 // This prevents race condition where sequential updateShape and removeShape calls
                                 // caused state overwrites (leading to hole not being saved).
                                 const updatedTarget = { ...target, holes: newHoles };
                                 replaceShapes([shape.id, target.id], [updatedTarget]);

                                 holeCreated = true;
                                 break; // Cut one object at a time
                             }
                         }
                     }
                }

                if (!holeCreated) {
                    // Normal extrude behavior
                    // If dragHeight is negative (and didn't cut), we clamp to 0.01 or handle as just shortening?
                    // Currently clamping minimum height to 0.01 to prevent inverted shapes or zero height
                    const updates: Partial<IShape> = { height: Math.max(0.01, ppState.dragHeight) }; 
                    if (shape.type === 'flat' && updates.height! > 0.05) { 
                        updates.type = 'solid'; 
                        if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR; 
                    } 
                    updateShape(ppState.hoveredShapeId, updates); 
                }
            }
        } 
        else if (tempShapeRef.current) { updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points }); }

        setTempShape(null); 
        setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined })); 
        setMeasurement('');
    }, [updateShape, removeShape, replaceShapes, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);

    useEffect(() => { if (isDragging) { const onGlobalPointerUp = () => handlePointerUp(); window.addEventListener('pointerup', onGlobalPointerUp); return () => window.removeEventListener('pointerup', onGlobalPointerUp); } }, [isDragging, handlePointerUp]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const ShapeRenderer: React.FC<ShapeRendererProps> = React.memo(({ 
    shape, isSelected, pushPullState, pushPullHandlers, 
    drawingHandlers, setDraggingState, onShapeRef 
}) => {
    const groupRef = useRef<THREE.Group>(null);
    const { updateShape, selectedIds } = useApp();
    const isMultiSelected = selectedIds.length > 1;

    useEffect(() => {
        if (groupRef.current) {
            onShapeRef(shape.id, groupRef.current);
        }
    }, [shape.id, onShapeRef]);

    const geometry = useMemo(() => {
        const threeShape = createThreeShape(shape.points, shape.holes);
        if (shape.type === 'solid') {
            return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
        } else {
            return new THREE.ShapeGeometry(threeShape);
        }
    }, [shape.points, shape.holes, shape.type, shape.height]);

    const material = useMemo(() => {
        const color = isSelected ? HIGHLIGHT_COLOR : (shape.type === 'flat' ? (shape.color === DEFAULT_COLOR ? FLAT_COLOR : shape.color) : shape.color);
        const opacity = shape.type === 'flat' ? 0.5 : 1;
        return new THREE.MeshStandardMaterial({ color, transparent: shape.type === 'flat', opacity, side: THREE.DoubleSide });
    }, [shape.color, shape.type, isSelected]);

    return (
        <group 
            ref={groupRef}
            position={new THREE.Vector3(...shape.position)} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={new THREE.Vector3(...shape.scale)}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                 e.stopPropagation();
                 drawingHandlers.handleClick(e);
            }}
            onPointerDown={(e) => {
                pushPullHandlers.handlePointerDown(e);
                drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={pushPullHandlers.handlePointerMove}
            onPointerUp={pushPullHandlers.handlePointerUp}
        >
             <mesh
                geometry={geometry}
                material={material}
                rotation={[-Math.PI / 2, 0, 0]}
                receiveShadow
                castShadow
            >
                {isSelected && <Edges color="white" linewidth={2} />}
            </mesh>
            {isSelected && !isMultiSelected && <DimensionShape shape={shape} isSelected={isSelected} onSelect={() => {}} />}
        </group>
    );
});

const SceneContent: React.FC = () => {
    const { 
        shapes, tool, selectedIds, selectShape, updateShape, 
        addShape, guideLines, activeLayerId, layers, transformMode, 
        formatValue, setMeasurement, deselectAll
    } = useApp();
    const { camera, gl } = useThree();
    const [drawingPoints, setDrawingPoints] = useState<IPoint[]>([]);
    const [mousePos, setMousePos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const shapeRefs = useRef<Record<string, THREE.Group | null>>({});

    const ppManager = usePushPullManager();

    useEffect(() => {
        setDrawingPoints([]);
        setSnapInfo(null);
    }, [tool]);

    const getGroundPoint = (e: ThreeEvent<PointerEvent>) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, target);
        return target || new THREE.Vector3(0, 0, 0);
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        const groundP = getGroundPoint(e);
        const ray = new THREE.Ray(camera.position, groundP.clone().sub(camera.position).normalize());

        const shouldSnap = [ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.MEASURE].includes(tool);
        let snap: SnapResult = { position: groundP, type: 'none', distance: 0, normal: new THREE.Vector3(0,1,0) };

        if (shouldSnap) {
             snap = getGeometrySnap(groundP, ray, shapes, drawingPoints, SNAP_THRESHOLD);
             if (snap.type === 'none' || snap.type === 'grid') {
                 snap.position.set(
                     Math.round(groundP.x / SNAP_GRID) * SNAP_GRID,
                     0,
                     Math.round(groundP.z / SNAP_GRID) * SNAP_GRID
                 );
                 snap.type = 'grid';
             }
        }

        setSnapInfo(snap);
        setMousePos(snap.position);

        if (drawingPoints.length > 0) {
            const start = drawingPoints[drawingPoints.length - 1];
            const dist = Math.sqrt((snap.position.x - start.x)**2 + (snap.position.z - start.z)**2);
            setMeasurement(`距離: ${formatValue(dist)}`);
        } else {
            if (tool === ToolType.SELECT && !ppManager.isDragging) setMeasurement('');
        }

        if (tool === ToolType.PUSH_PULL) {
            ppManager.handlePointerMove(e);
        }
    };

    const handleCanvasClick = (e: ThreeEvent<MouseEvent>) => {
        if (isDragging) return;

        if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) {
            const p = { x: mousePos.x, y: 0, z: mousePos.z };

            if (tool === ToolType.DRAW_RECT) {
                if (drawingPoints.length === 0) {
                    setDrawingPoints([p]);
                } else {
                    const start = drawingPoints[0];
                    const width = Math.abs(p.x - start.x);
                    const depth = Math.abs(p.z - start.z);
                    if (width < 0.1 || depth < 0.1) return;

                    const center = { x: (start.x + p.x)/2, z: (start.z + p.z)/2 };
                    const halfW = width / 2;
                    const halfD = depth / 2;

                    const points = [
                        { x: -halfW, y: 0, z: -halfD },
                        { x: halfW, y: 0, z: -halfD },
                        { x: halfW, y: 0, z: halfD },
                        { x: -halfW, y: 0, z: halfD },
                        { x: -halfW, y: 0, z: -halfD }
                    ];

                    addShape({
                        id: `rect-${Date.now()}`,
                        type: 'solid',
                        points,
                        height: 3,
                        color: DEFAULT_COLOR,
                        layerId: activeLayerId,
                        position: [center.x, 0, center.z],
                        rotation: [0, 0, 0],
                        scale: [1, 1, 1],
                        name: 'Room'
                    });
                    setDrawingPoints([]);
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 if (drawingPoints.length === 0) setDrawingPoints([p]);
                 else {
                     const center = drawingPoints[0];
                     const radius = Math.sqrt((p.x - center.x)**2 + (p.z - center.z)**2);
                     if (radius < 0.1) return;
                     const points = createCirclePoints(radius);
                     addShape({
                        id: `circle-${Date.now()}`,
                        type: 'flat',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        layerId: activeLayerId,
                        position: [center.x, 0, center.z],
                        rotation: [0, 0, 0],
                        scale: [1, 1, 1],
                        name: 'Circle'
                     });
                     setDrawingPoints([]);
                 }
            } else if (tool === ToolType.DRAW_LINE) {
                setDrawingPoints(prev => [...prev, p]);
                if (drawingPoints.length > 2) {
                    const start = drawingPoints[0];
                    const dist = Math.sqrt((p.x - start.x)**2 + (p.z - start.z)**2);
                    if (dist < 0.3) {
                         const minX = Math.min(...drawingPoints.map(dp=>dp.x));
                         const maxX = Math.max(...drawingPoints.map(dp=>dp.x));
                         const minZ = Math.min(...drawingPoints.map(dp=>dp.z));
                         const maxZ = Math.max(...drawingPoints.map(dp=>dp.z));
                         const centerX = (minX + maxX)/2;
                         const centerZ = (minZ + maxZ)/2;

                         const localPoints = drawingPoints.map(dp => ({ x: dp.x - centerX, y: 0, z: dp.z - centerZ }));
                         localPoints.push(localPoints[0]);

                         addShape({
                            id: `poly-${Date.now()}`,
                            type: 'flat',
                            points: localPoints,
                            height: DEFAULT_HEIGHT,
                            color: FLAT_COLOR,
                            layerId: activeLayerId,
                            position: [centerX, 0, centerZ],
                            rotation: [0, 0, 0],
                            scale: [1, 1, 1],
                            name: 'Polygon'
                        });
                        setDrawingPoints([]);
                    }
                }
            }
        }
        else if (tool === ToolType.SELECT) {
             if (!e.intersections.some(i => i.object.userData?.isShape || i.object.parent?.userData?.isShape)) {
                 deselectAll();
             }
        }
    };

    const activeTransformMode = tool === ToolType.ROTATE ? 'rotate' : transformMode;
    const showTransformControls = selectedIds.length === 1 && (tool === ToolType.SELECT || tool === ToolType.ROTATE);

    return (
        <>
            <gridHelper args={[100, 100, 0xdddddd, 0xeeeeee]} />
            <axesHelper args={[5]} />
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow />

            <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]} 
                onPointerMove={handlePointerMove} 
                onClick={handleCanvasClick}
                visible={false}
            >
                <planeGeometry args={[1000, 1000]} />
            </mesh>

            <GuideLinesRenderer lines={guideLines} />

            {shapes.map(shape => {
                const layer = layers.find(l => l.id === shape.layerId);
                if (layer && !layer.visible) return null;

                return (
                    <ShapeRenderer 
                        key={shape.id} 
                        shape={ppManager.tempShape?.id === shape.id ? ppManager.tempShape : shape}
                        isSelected={selectedIds.includes(shape.id)}
                        pushPullState={ppManager.ppState}
                        pushPullHandlers={ppManager}
                        drawingHandlers={{ 
                            handlePointerDown: (e) => {
                                if (tool === ToolType.SELECT) {
                                    e.stopPropagation();
                                    const multi = e.shiftKey;
                                    selectShape(shape.id, multi);
                                }
                            },
                            handlePointerUp: () => {},
                            handleClick: (e) => {}
                        }}
                        rotateHandlers={{ handleClick: () => {}, handlePointerMove: () => {} }}
                        setDraggingState={setIsDragging}
                        onShapeRef={(id, ref) => { shapeRefs.current[id] = ref; }}
                        shapeRefs={shapeRefs}
                        setAlignmentLines={() => {}}
                    />
                );
            })}

            {drawingPoints.length > 0 && (
                <group>
                    {drawingPoints.map((p, i) => (
                        <mesh key={i} position={[p.x, 0.1, p.z]}>
                            <sphereGeometry args={[0.05]} />
                            <meshBasicMaterial color="red" />
                        </mesh>
                    ))}
                    {tool === ToolType.DRAW_RECT && (
                         <SimpleLine points={[
                            new THREE.Vector3(drawingPoints[0].x, 0.1, drawingPoints[0].z),
                            new THREE.Vector3(mousePos.x, 0.1, drawingPoints[0].z),
                            new THREE.Vector3(mousePos.x, 0.1, mousePos.z),
                            new THREE.Vector3(drawingPoints[0].x, 0.1, mousePos.z),
                            new THREE.Vector3(drawingPoints[0].x, 0.1, drawingPoints[0].z)
                         ]} color="blue" />
                    )}
                    {tool === ToolType.DRAW_CIRCLE && (
                         <SimpleLine points={[
                             new THREE.Vector3(drawingPoints[0].x, 0.1, drawingPoints[0].z),
                             new THREE.Vector3(mousePos.x, 0.1, mousePos.z)
                         ]} color="blue" dashed />
                    )}
                    {tool === ToolType.DRAW_LINE && (
                         <SimpleLine points={[...drawingPoints.map(p => new THREE.Vector3(p.x, 0.1, p.z)), new THREE.Vector3(mousePos.x, 0.1, mousePos.z)]} color="blue" />
                    )}
                </group>
            )}

            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {snapInfo && <CursorTooltip text={snapInfo.type !== 'grid' && snapInfo.type !== 'none' ? snapInfo.type : ''} position={snapInfo.position} type={snapInfo.type} />}

            {showTransformControls && shapeRefs.current[selectedIds[0]] && (
                <TransformControls 
                    object={shapeRefs.current[selectedIds[0]]!} 
                    mode={activeTransformMode} 
                    onDraggingChanged={(e: any) => setIsDragging(e.value)} 
                    onMouseUp={() => {
                        const obj = shapeRefs.current[selectedIds[0]];
                        if (obj) {
                             updateShape(selectedIds[0], {
                                 position: [obj.position.x, obj.position.y, obj.position.z],
                                 rotation: [obj.rotation.x, obj.rotation.y, obj.rotation.z],
                                 scale: [obj.scale.x, obj.scale.y, obj.scale.z]
                             });
                        }
                    }}
                />
            )}
        </>
    );
};

const Viewport: React.FC = () => {
    const { currentView, setCurrentView } = useApp();
    const orbitRef = useRef<any>(null);

    useEffect(() => {
        if (!currentView || !orbitRef.current) return;
        const controls = orbitRef.current;
        switch (currentView) {
            case 'top':
                controls.object.position.set(0, 20, 0);
                controls.object.lookAt(0, 0, 0);
                break;
            case 'front':
                controls.object.position.set(0, 2, 20);
                controls.object.lookAt(0, 2, 0);
                break;
            case 'right':
                controls.object.position.set(20, 2, 0);
                controls.object.lookAt(0, 2, 0);
                break;
            case 'left':
                 controls.object.position.set(-20, 2, 0);
                 controls.object.lookAt(0, 2, 0);
                 break;
            case 'bottom':
                 controls.object.position.set(0, -20, 0);
                 controls.object.lookAt(0, 0, 0);
                 break;
        }
        controls.update();
        setCurrentView(null);
    }, [currentView, setCurrentView]);

    return (
        <div className="w-full h-full bg-slate-100">
            <Canvas shadows camera={{ position: [8, 8, 8], fov: 45 }}>
                <OrbitControls ref={orbitRef} makeDefault />
                <SceneContent />
                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#9d4b4b', '#2f7f4f', '#3b5b9d']} labelColor="white" />
                </GizmoHelper>
            </Canvas>
        </div>
    );
};

