};

const SelectionGizmo: React.FC<{ setDragging: (d: boolean) => void, shapeRefs: any }> = ({ setDragging, shapeRefs }) => {
    const { selectedIds, updateShapes, transformMode } = useApp();
    const selectedId = selectedIds[selectedIds.length - 1];
    const object = selectedId ? shapeRefs.current[selectedId] : undefined;

    return object ? (
        <TransformControls object={object} mode={transformMode} onDragging-changed={e => setDragging(e.value)} 
            onMouseUp={() => {
                 if (object) {
                     updateShapes([{ id: selectedId, changes: { position: object.position.toArray(), rotation: [object.rotation.x, object.rotation.y, object.rotation.z], scale: object.scale.toArray() } }]);
                 }
